// Freehand coordinates are normalized to the original floor overview, independent of zoom.
const floors={'N-1':'',N01:'n01/',N02:'n02/',N03:'n03/'};
export function latestPaymentPlan(rows,contractor){return structuredClone(rows.filter(r=>r.contractor===contractor&&r.plan).sort((a,b)=>String(b.period).localeCompare(String(a.period))||String(b.at).localeCompare(String(a.at)))[0]?.plan||{schema:1,floors:{}});}
export function validatePlan(plan){if(plan==null)return;if(plan.schema!==1||!plan.floors||JSON.stringify(plan).length>40000)throw Error('Plano demasiado grande o incompatible.');for(const [floor,sheet]of Object.entries(plan.floors)){if(!(floor in floors)||!Array.isArray(sheet.strokes)||sheet.strokes.length>300)throw Error('Plano inválido');for(const stroke of sheet.strokes){if(!['#21854b','#d68b20','#c83c3c'].includes(stroke.color)||!Array.isArray(stroke.points)||stroke.points.length<1||stroke.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isFinite(n)||n<0||n>1)))throw Error('Trazo inválido');}}}
export async function openPaymentPlan(plan,onSave,{readOnly=false}={}){
 const draft=structuredClone(plan||{schema:1,floors:{}}),dialog=document.createElement('dialog');dialog.className='paymentPlan';dialog.innerHTML='<h2>Avance dibujado del pago</h2><p>Verde: ejecutado · Naranja: pendiente · Rojo: observación. El dibujo es una anotación; no calcula cantidades.</p><div class="planTools"><select aria-label="Piso del dibujo"><option value="N-1">Piso −1</option><option value="N01">Piso 1</option><option value="N02">Piso 2</option><option value="N03">Piso 3</option></select><button type="button" data-mode="draw">Lápiz</button><button type="button" data-mode="pan">Mover</button><select aria-label="Estado del trazo"><option value="#21854b">Ejecutado</option><option value="#d68b20">Pendiente</option><option value="#c83c3c">Observación</option></select><button type="button" data-zoom="0.7">+</button><button type="button" data-zoom="1.4">−</button><button type="button" id="undoPlan">Deshacer trazo</button></div><p class="planStatus" role="status"></p><svg class="paymentPlanSvg" xmlns="http://www.w3.org/2000/svg"><image/><g/></svg><button type="button" id="applyPlan">Conservar dibujo en este formulario</button><button type="button" id="cancelPlan">Cancelar</button><p>Para guardarlo en la nube, pulsa Guardar en el estado de pago.</p>';
 document.body.append(dialog);if(readOnly){dialog.querySelector('h2').textContent='Plano guardado · solo lectura';dialog.querySelector('#applyPlan').hidden=true;dialog.querySelector('#undoPlan').hidden=true;dialog.querySelector('[data-mode=draw]').hidden=true;dialog.querySelectorAll('select')[1].hidden=true;dialog.querySelector('#cancelPlan').textContent='Cerrar';dialog.querySelector('p:last-child').textContent='Copia del dibujo guardado en esta versión del pago.';}dialog.showModal();const svg=dialog.querySelector('svg'),image=svg.querySelector('image'),group=svg.querySelector('g'),selectors=dialog.querySelectorAll('select'),status=dialog.querySelector('.planStatus');let floor='N-1',mode=readOnly?'pan':'draw',width=1000,height=1000,view=[0,0,1000,1000],active=null,serial=0;
 const updateView=()=>svg.setAttribute('viewBox',view.join(' '));const render=()=>{group.innerHTML='';for(const stroke of draft.floors[floor]?.strokes||[]){const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',stroke.points.map((p,i)=>(i?'L':'M')+(p[0]*width)+' '+(p[1]*height)).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke',stroke.color);path.setAttribute('stroke-width',String(width*.003));path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');group.append(path);}};
 async function load(){const request=++serial;active=null;status.textContent='Cargando plano…';svg.style.pointerEvents='none';const url=floors[floor]+'map/overview.webp',img=new Image();img.src=url;try{await img.decode();if(request!==serial||!dialog.isConnected)return;width=img.naturalWidth;height=img.naturalHeight;image.setAttribute('href',url);image.setAttribute('width',width);image.setAttribute('height',height);view=[0,0,width,height];updateView();draft.floors[floor]??={source:url,strokes:[]};render();svg.style.pointerEvents='auto';status.textContent='Lápiz dibuja; Mover desplaza el plano. Usa + para acercar.';}catch{status.textContent='No se pudo cargar el plano de este piso.';}}
 selectors[0].onchange=()=>{floor=selectors[0].value;load();};dialog.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;dialog.querySelectorAll('[data-mode]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));});dialog.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.zoom);if(view[2]*k<width/30||view[2]*k>width*2)return;view=[view[0]+view[2]*(1-k)/2,view[1]+view[3]*(1-k)/2,view[2]*k,view[3]*k];updateView();});
 const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());svg.onpointerdown=e=>{if(active)return;e.preventDefault();svg.setPointerCapture(e.pointerId);const p=point(e);if(mode==='draw'){const stroke={color:selectors[1].value,points:[[Math.max(0,Math.min(1,p.x/width)),Math.max(0,Math.min(1,p.y/height))]]};draft.floors[floor].strokes.push(stroke);active={id:e.pointerId,stroke};render();}else active={id:e.pointerId,x:e.clientX,y:e.clientY,view:[...view],scale:svg.getScreenCTM().a};};svg.onpointermove=e=>{if(active?.id!==e.pointerId)return;e.preventDefault();if(active.stroke){const p=point(e);active.stroke.points.push([Math.round(Math.max(0,Math.min(1,p.x/width))*10000)/10000,Math.round(Math.max(0,Math.min(1,p.y/height))*10000)/10000]);render();}else{view=[active.view[0]-(e.clientX-active.x)/active.scale,active.view[1]-(e.clientY-active.y)/active.scale,active.view[2],active.view[3]];updateView();}};svg.onpointerup=e=>{if(active?.id===e.pointerId)active=null;};svg.onpointercancel=e=>{if(active?.id===e.pointerId){if(active.stroke)draft.floors[floor].strokes.pop();active=null;render();}};
 dialog.querySelector('#undoPlan').onclick=()=>{draft.floors[floor]?.strokes.pop();render();};const close=()=>{serial++;dialog.remove();};dialog.oncancel=e=>{e.preventDefault();close();};dialog.querySelector('#cancelPlan').onclick=close;dialog.querySelector('#applyPlan').onclick=()=>{try{validatePlan(draft);onSave(draft);close();}catch(error){status.textContent=error.message;}};await load();
}
